import csv
import io
from collections import OrderedDict
from typing import List, Dict, Any, Tuple

def parse_csv(raw_csv: str) -> Tuple[List[str], List[List[str]]]:
    """
    Parses a raw CSV string into a dictionary with keys 'columns' and 'rows'.

    Returns:
        (headers, rows): A tuple of (list of strings, list of lists of strings).
        If successful, returns the parsed data.
        If parsing fails, returns None.
    """
    # Initialize headers as a dictionary to handle quoted fields properly
    headers = OrderedDict()

    # Read header row
    try:
        header_line = raw_csv.strip().split('\n')
        if not header_line:
            return None, []

        # Parse the header line
        header_parts = header_line[0].strip().split(',')
        for part in header_parts:
            if part and '=' in part:  # Handle quoted fields with equals signs
                field_name = part.split('=', 1)[0]
                value = part.split('=', 1)[1]
                headers[field_name] = value
            else:
                headers[part.strip()] = None
    except Exception:
        return None, []

    # Read remaining lines
    try:
        if len(raw_csv) > 0 and raw_csv.strip().endswith('\n'):
            raw_csv = raw_csv[:-1]

        rows = []
        current_row = []

        for line in raw_csv.split('\n'):
            row_parts = line.strip().split(',')

            # Skip empty lines
            if not row_parts:
                continue

            # Parse the current row
            current_row = []
            for part in row_parts:
                if '=' in part:
                    field_name, value = part.split('=', 1)
                    current_row.append(field_name)
                    current_row.append(value.strip())
                else:
                    current_row.append(part.strip())

            # Check if this is a new header or data row
            if len(current_row) == 0:
                # This is a new header line, add it to headers
                for part in raw_csv.split('\n'):
                    if '=' in part and not part.startswith('') and not part.endswith(''):
                        field_name = part.split('=', 1)[0].strip()
                        value = part.split('=', 1)[1].strip()
                        headers[field_name] = value
            else:
                # This is a data row, add it to rows
                rows.append(current_row)

        return headers, rows

    except Exception:
        return None, []

def main():
    """Main entry point for CSV parsing."""
    raw_csv = "Sample CSV content here"

    try:
        headers, rows = parse_csv(raw_csv)

        if headers is not None and len(rows) > 0:
            print(f"Parsed {len(headers)} columns from {len(rows)} rows")
            for i, row in enumerate(rows):
                print(row)
        else:
            print("Failed to parse CSV")
    except Exception as e:
        print(f"Error parsing CSV: {e}")

if __name__ == "__main__":
    main()
